BY_CODE: Dict[str, Subject] = {s["ths_code"]: s for s in SUBJECTS}


def subjects_for(statement: str) -> List[Subject]:
    """按报表取科目（保持模板行序）。"""
    return [s for s in SUBJECTS if s["statement"] == statement]


def codes_for(statement: str) -> List[str]:
    return [s["ths_code"] for s in subjects_for(statement)]


def display_name(ths_code: str) -> Optional[str]:
    """科目中文名；未知码返回 None。"""
    s = BY_CODE.get(ths_code)
    return s["name"] if s else None


def resolve_name(name: str) -> Optional[Subject]:
    """模板中文名 → 科目；未命中返回 None（大小写无关）。"""
    want = name.strip().lower()
    for s in SUBJECTS:
        if s["name"].lower() == want:
            return s
    return None
